CREATE TABLE ops.pdf_stage_artifact_part (
	product_id TEXT NOT NULL, 
	revision_id TEXT NOT NULL, 
	stream_id TEXT NOT NULL, 
	ordinal BIGINT NOT NULL, 
	byte_offset BIGINT NOT NULL, 
	byte_length BIGINT NOT NULL, 
	body BYTEA NOT NULL, 
	sha256_digest TEXT NOT NULL, 
	CONSTRAINT pk_pdf_stage_artifact_part PRIMARY KEY (product_id, revision_id, stream_id, ordinal), 
	CONSTRAINT ck_pdf_stage_artifact_part_ordinal_ee668cd4ef CHECK (ordinal >= 0), 
	CONSTRAINT ck_pdf_stage_artifact_part_byte_offset_5dc7051d0c CHECK (byte_offset >= 0), 
	CONSTRAINT ck_pdf_stage_artifact_part_byte_length_0392ce7ab3 CHECK (byte_length >= 0), 
	CONSTRAINT ck_pdf_stage_artifact_part_physical_9cde4d345e CHECK (byte_length = octet_length(body)), 
	CONSTRAINT ck_pdf_stage_artifact_part_physical_f369db0b22 CHECK (byte_length > 0), 
	CONSTRAINT ck_pdf_stage_artifact_part_physical_3bbd16db25 CHECK (byte_length <= 65536), 
	CONSTRAINT ck_pdf_stage_artifact_part_physical_266e3bac59 CHECK (sha256_digest = encode(sha256(body),'hex')), 
	CONSTRAINT ck_pdf_stage_artifact_part_physical_a18559f6de CHECK (product_id = revision_id)
);
CREATE TABLE ops.pdf_stage_artifact_stream (
	product_id TEXT NOT NULL, 
	revision_id TEXT NOT NULL, 
	stream_id TEXT NOT NULL, 
	byte_length BIGINT NOT NULL, 
	serialization_sha256 TEXT NOT NULL, 
	byte_root TEXT NOT NULL, 
	encoding_profile TEXT NOT NULL, 
	CONSTRAINT pk_pdf_stage_artifact_stream PRIMARY KEY (product_id, revision_id, stream_id), 
	CONSTRAINT ck_pdf_stage_artifact_stream_byte_length_0392ce7ab3 CHECK (byte_length >= 0), 
	CONSTRAINT ck_pdf_stage_artifact_stream_physical_94d0a9f5c9 CHECK (stream_id <> ''), 
	CONSTRAINT ck_pdf_stage_artifact_stream_physical_353c63835f CHECK (serialization_sha256 ~ '^[0-9a-f]{64}$'), 
	CONSTRAINT ck_pdf_stage_artifact_stream_physical_860f4eb238 CHECK (byte_root ~ '^[0-9a-f]{64}$'), 
	CONSTRAINT ck_pdf_stage_artifact_stream_physical_66ee4db5f7 CHECK (encoding_profile <> ''), 
	CONSTRAINT ck_pdf_stage_artifact_stream_physical_a18559f6de CHECK (product_id = revision_id)
);
CREATE TABLE ops.pdf_stage_build (
	build_id TEXT NOT NULL, 
	task_id BIGINT NOT NULL, 
	run_id BIGINT NOT NULL, 
	release_id TEXT NOT NULL, 
	source_digest TEXT NOT NULL, 
	recipe_digest TEXT NOT NULL, 
	schema_digest TEXT NOT NULL, 
	replay_key TEXT NOT NULL, 
	attempt BIGINT NOT NULL, 
	holder TEXT NOT NULL, 
	state TEXT NOT NULL, 
	CONSTRAINT pk_pdf_stage_build PRIMARY KEY (build_id), 
	CONSTRAINT ck_pdf_stage_build_state_987307e7e8 CHECK (state IN ('abandoned', 'open')), 
	CONSTRAINT uq_pdf_stage_build_task_id_replay_key UNIQUE (task_id, replay_key), 
	CONSTRAINT ck_pdf_stage_build_physical_8147daae94 CHECK (build_id <> ''), 
	CONSTRAINT ck_pdf_stage_build_physical_1b32a362eb CHECK (source_digest ~ '^[0-9a-f]{64}$'), 
	CONSTRAINT ck_pdf_stage_build_physical_3058c3002b CHECK (recipe_digest ~ '^[0-9a-f]{64}$'), 
	CONSTRAINT ck_pdf_stage_build_physical_6416099f87 CHECK (schema_digest ~ '^[0-9a-f]{64}$'), 
	CONSTRAINT ck_pdf_stage_build_physical_0c8a59b69d CHECK (attempt > 0)
);
