	product_id TEXT NOT NULL, 
	revision_id TEXT NOT NULL, 
	release_id TEXT NOT NULL, 
	source_digest TEXT NOT NULL, 
	mapping_profile TEXT NOT NULL, 
	contract_version TEXT NOT NULL, 
