	CONSTRAINT ck_pdf_stage_document_physical_1246cec1c1 CHECK (product_id <> ''), 
	CONSTRAINT ck_pdf_stage_document_physical_b85b787d88 CHECK (revision_id <> ''), 
	CONSTRAINT ck_pdf_stage_document_physical_26e3a40d89 CHECK (native_schema_digest ~ '^[0-9a-f]{64}$'), 
	CONSTRAINT ck_pdf_stage_document_physical_1b32a362eb CHECK (source_digest ~ '^[0-9a-f]{64}$'), 
	CONSTRAINT ck_pdf_stage_document_physical_a18559f6de CHECK (product_id = revision_id)
);
CREATE TABLE ops.pdf_stage_membership (
	product_id TEXT NOT NULL, 
	revision_id TEXT NOT NULL, 
	parent_id TEXT NOT NULL, 
	field_name TEXT NOT NULL, 
	ordinal BIGINT NOT NULL, 
	member_key TEXT, 
	member_key_stream_id TEXT, 
	value_kind TEXT NOT NULL, 
	record_id TEXT, 
	scalar_json JSONB, 
	stream_id TEXT, 
	CONSTRAINT pk_pdf_stage_membership PRIMARY KEY (product_id, revision_id, parent_id, field_name, ordinal), 
	CONSTRAINT ck_pdf_stage_membership_ordinal_ee668cd4ef CHECK (ordinal >= 0), 
	CONSTRAINT ck_pdf_stage_membership_value_kind_1ee79cbd9a CHECK (value_kind IN ('parts', 'record', 'scalar')), 
	CONSTRAINT ck_pdf_stage_membership_physical_b66e6eb309 CHECK (octet_length(convert_to(scalar_json::text,'UTF8')) <= 65536), 
	CONSTRAINT ck_pdf_stage_membership_physical_8028c34622 CHECK ((value_kind = 'record') = (record_id IS NOT NULL)), 
	CONSTRAINT ck_pdf_stage_membership_physical_df9d6518cd CHECK ((value_kind = 'parts') = (stream_id IS NOT NULL)), 
	CONSTRAINT ck_pdf_stage_membership_physical_341b42c0f9 CHECK (value_kind = 'scalar' OR scalar_json IS NULL), 
	CONSTRAINT ck_pdf_stage_membership_physical_8bf5b8b4d7 CHECK (member_key IS NULL OR member_key_stream_id IS NULL), 
	CONSTRAINT ck_pdf_stage_membership_physical_a18559f6de CHECK (product_id = revision_id)
);
CREATE TABLE ops.pdf_stage_native (
	product_id TEXT NOT NULL, 
	revision_id TEXT NOT NULL, 
	record_id TEXT NOT NULL, 
	native_type TEXT NOT NULL, 
	family TEXT NOT NULL, 
	native_address TEXT, 
	native_address_stream_id TEXT, 
	scalars_json JSONB NOT NULL, 
	structure_json JSONB NOT NULL, 
	CONSTRAINT pk_pdf_stage_native PRIMARY KEY (product_id, revision_id, record_id), 
	CONSTRAINT ck_pdf_stage_native_family_896b469851 CHECK (family IN ('cell', 'detail', 'header', 'node', 'page', 'provenance', 'reference', 'table')), 
	CONSTRAINT uq_pdf_stage_native_product_id_revision_id_native_address UNIQUE (product_id, revision_id, native_address), 
	CONSTRAINT ck_pdf_stage_native_physical_d10d461f9b CHECK (record_id <> ''), 
	CONSTRAINT ck_pdf_stage_native_physical_1e27d9c8ce CHECK (native_type <> ''), 
	CONSTRAINT ck_pdf_stage_native_physical_af247a6f3c CHECK (jsonb_typeof(scalars_json) = 'object'), 
	CONSTRAINT ck_pdf_stage_native_physical_39016badae CHECK (jsonb_typeof(structure_json) = 'object'), 
	CONSTRAINT ck_pdf_stage_native_physical_c4ce4d92f6 CHECK (octet_length(convert_to(scalars_json::text,'UTF8')) <= 65536), 
	CONSTRAINT ck_pdf_stage_native_physical_c09752f060 CHECK (octet_length(convert_to(structure_json::text,'UTF8')) <= 65536), 
	CONSTRAINT ck_pdf_stage_native_physical_4c7b8c414a CHECK ((native_address IS NULL) <> (native_address_stream_id IS NULL)), 
	CONSTRAINT ck_pdf_stage_native_physical_a18559f6de CHECK (product_id = revision_id)
);
CREATE TABLE ops.pdf_stage_receipt (
	build_id TEXT NOT NULL, 
	replay_key TEXT NOT NULL, 
	content_digest TEXT NOT NULL, 
	row_count BIGINT NOT NULL, 
	CONSTRAINT pk_pdf_stage_receipt PRIMARY KEY (build_id, replay_key), 
