CREATE TABLE ops.pdf_stage_reference (
	product_id TEXT NOT NULL, 
	revision_id TEXT NOT NULL, 
	reference_id TEXT NOT NULL, 
	source_id TEXT NOT NULL, 
	field_name TEXT NOT NULL, 
	native_pointer TEXT, 
	native_pointer_stream_id TEXT, 
	target_id TEXT, 
	CONSTRAINT pk_pdf_stage_reference PRIMARY KEY (product_id, revision_id, reference_id), 
	CONSTRAINT ck_pdf_stage_reference_physical_b4d49caa5d CHECK (reference_id <> ''), 
	CONSTRAINT ck_pdf_stage_reference_physical_84ee799da6 CHECK ((field_name IN ('source_cell_id','target_cell_id') AND native_pointer ~ '^-?[0-9]+$') OR (field_name NOT IN ('source_cell_id','target_cell_id') AND native_pointer LIKE '#%%')), 
	CONSTRAINT ck_pdf_stage_reference_physical_15d32f6137 CHECK ((native_pointer IS NULL) <> (native_pointer_stream_id IS NULL)), 
	CONSTRAINT ck_pdf_stage_reference_physical_a18559f6de CHECK (product_id = revision_id)
);
