d ? 'orientation' AND (nested_record->>'orientation')::numeric < 0) OR (nested_record ? 'orientation' AND (nested_record->>'orientation')::numeric > 0) OR NOT (nested_record ? 'outcome') OR (nested_record ? 'outcome' AND (jsonb_typeof(nested_record->'outcome') IS DISTINCT FROM 'string' OR nested_record->>'outcome' NOT IN ('complete','partial','unknown'))) OR NOT (nested_record ? 'lines') OR (nested_record ? 'lines' AND (jsonb_typeof(nested_record->'lines') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(nested_record->'lines') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['line_index','text','words'])) OR NOT (nested_record ? 'line_index') OR (nested_record ? 'line_index' AND (jsonb_typeof(nested_record->'line_index') IS DISTINCT FROM 'number' OR nested_record->>'line_index' !~ '^[0-9]+$')) OR (nested_record ? 'line_index' AND (nested_record->>'line_index')::numeric < 0) OR NOT (nested_record ? 'text') OR (nested_record ? 'text' AND (jsonb_typeof(nested_record->'text') IS DISTINCT FROM 'string')) OR NOT (nested_record ? 'words') OR (nested_record ? 'words' AND (jsonb_typeof(nested_record->'words') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(nested_record->'words') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['word_index','text','confidence','start','end','raster_left','raster_top','raster_right','raster_bottom','left','top','right','bottom'])) OR NOT (nested_record ? 'word_index') OR (nested_record ? 'word_index' AND (jsonb_typeof(nested_record->'word_index') IS DISTINCT FROM 'number' OR nested_record->>'word_index' !~ '^[0-9]+$')) OR (nested_record ? 'word_index' AND (nested_record->>'word_index')::numeric < 0) OR NOT (nested_record ? 'text') OR (nested_record ? 'text' AND (jsonb_typeof(nested_record->'text