b_array_length(nested_record->'lines') < 1)) OR NOT (nested_record ? 'left') OR (nested_record ? 'left' AND (jsonb_typeof(nested_record->'left') IS DISTINCT FROM 'number')) OR NOT (nested_record ? 'top') OR (nested_record ? 'top' AND (jsonb_typeof(nested_record->'top') IS DISTINCT FROM 'number')) OR NOT (nested_record ? 'right') OR (nested_record ? 'right' AND (jsonb_typeof(nested_record->'right') IS DISTINCT FROM 'number')) OR NOT (nested_record ? 'bottom') OR (nested_record ? 'bottom' AND (jsonb_typeof(nested_record->'bottom') IS DISTINCT FROM 'number')))))))))) OR (parsing_item ? 'derivation_mappings' AND (jsonb_typeof(parsing_item->'derivation_mappings') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'derivation_mappings') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['pointer','origin_pointer','source_field','start','end','cell_index','kind'])) OR NOT (nested_record ? 'pointer') OR (nested_record ? 'pointer' AND (jsonb_typeof(nested_record->'pointer') IS DISTINCT FROM 'string')) OR (nested_record ? 'pointer' AND nested_record->>'pointer' !~ '^#(/[^/]+)+$') OR NOT (nested_record ? 'origin_pointer') OR (nested_record ? 'origin_pointer' AND (jsonb_typeof(nested_record->'origin_pointer') IS DISTINCT FROM 'string')) OR (nested_record ? 'origin_pointer' AND nested_record->>'origin_pointer' !~ '^#(/[^/]+)+$') OR NOT (nested_record ? 'source_field') OR (nested_record ? 'source_field' AND (jsonb_typeof(nested_record->'source_field') IS DISTINCT FROM 'string' OR nested_record->>'source_field' NOT IN ('cell_text','text'))) OR NOT (nested_record ? 'start') OR (nested_record ? 'start' AND (jsonb_typeof(nested_record->'start') IS DISTINCT FROM 'number' OR nested_record->>'start' !~ '^[0-9]+$')) OR (nested_record ? 'start' AND (nested_record->>'start')::numeric < 0) OR NOT (nested_record ? 'end') OR (nested_record ? 'end' AND (jsonb_typeof(nested_record->'end') IS DISTINCT FROM 'number' OR nested_record->>'end' !~ '^[0-9]+$')) OR (nested_record ? 'end' AND (nested_record->>'end')::numeric < 0) OR (nested_record ? 'cell_index' AND (jsonb_typeof(nested_record->'cell_index') IS DISTINCT FROM 'number' OR nested_record->>'cell_index' !~ '^[0-9]+$')) OR (nested_record ? 'cell_index' AND (nested_record->>'cell_index')::numeric < 0) OR NOT (nested_record ? 'kind') OR (nested_record ? 'kind' AND (jsonb_typeof(nested_record->'kind') IS DISTINCT FROM 'string' OR nested_record->>'kind' NOT IN ('native_text_range','table_cell','vector_region_anchor')))))))))) THEN RAISE EXCEPTION 'parsing record shape differs: PdfIntegratedProduct' USING ERRCODE='23514'; END IF;

