 IF NOT EXISTS(SELECT FROM sem.input WHERE release_id=run.release_id AND input_kind='dependency' AND input_name='execution/schema/pdf_products' AND encode(sha256(content),'hex')=p_contract) THEN RAISE EXCEPTION 'PDF contract is not archived by task release' USING ERRCODE='23514'; END IF;
 SELECT artifact_digest INTO STRICT original FROM ops.source_build WHERE task_id=p_task AND release_id=run.release_id;
 IF product->>'artifact_digest' IS DISTINCT FROM original THEN RAISE EXCEPTION 'PDF original custody differs' USING ERRCODE='23514'; END IF;
 SELECT * INTO previous FROM ops.pdf_product WHERE task_id=p_task AND product_key=product->>'product_key';
 IF FOUND THEN
  IF previous.content_digest<>digest OR previous.contract_digest<>p_contract OR previous.kind<>product->>'kind' OR NOT EXISTS(SELECT FROM ops.pdf_product_body WHERE task_id=p_task AND product_key=product->>'product_key' AND payload=p_payload) THEN RAISE EXCEPTION 'immutable PDF bundle replay differs' USING ERRCODE='23514'; END IF;
  IF EXISTS((SELECT encode(sha256(supplied.content),'hex') FROM unnest(p_artifacts) supplied(content) EXCEPT SELECT a.artifact_digest FROM ops.pdf_product_artifact a WHERE a.task_id=p_task AND a.product_key=product->>'product_key') UNION ALL (SELECT a.artifact_digest FROM ops.pdf_product_artifact a WHERE a.task_id=p_task AND a.product_key=product->>'product_key' EXCEPT SELECT encode(sha256(supplied.content),'hex') FROM unnest(p_artifacts) supplied(content))) OR EXISTS(SELECT FROM unnest(p_artifacts) supplied(content) WHERE NOT EXISTS(SELECT FROM kb.source_artifact a WHERE a.artifact_digest=encode(sha256(supplied.content),'hex') AND a.content=supplied.content)) THEN RAISE EXCEPTION 'PDF replay artifacts differ' USING ERRCODE='23514'; END IF;
  RETURN digest;
 END IF;
 PERFORM sem.require_execution_operation(run.release_id,'publish_integrated_pdf');
 IF run.sealed OR run.status NOT IN ('created','running') OR job.status<>'running' THEN RAISE EXCEPTION 'run/attempt no longer accepts integrated PDF products' USING ERRCODE='P0004'; END IF;
 -- Resolve EVERY input before inserting the new identity. Immutable edges to extant bodies
 -- make forward references, self references and cycles impossible without a path table.
 FOR input,idx IN SELECT value::jsonb,n-1 FROM json_array_elements(input_rows) WITH ORDINALITY i(value,n) LOOP
  IF jsonb_typeof(input) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfProductInput' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(input) key WHERE key<>ALL(ARRAY['role','task_id','product_key','content_digest'])) OR NOT (input ? 'role') OR (input ? 'role' AND (jsonb_typeof(input->'role') IS DISTINCT FROM 'string' OR input->>'role' NOT IN ('alternative','policy_input','recognition','structural'))) OR NOT (input ? 'task_id') OR (input ? 'task_id' AND (jsonb_typeof(input->'task_id') IS DISTINCT FROM 'number' OR input->>'task_id' !~ '^[0-9]+$')) OR (input ? 'task_id' AND (input->>'task_id')::numeric < 1) OR NOT (input ? 'product_key') OR (input ? 'product_key' AND (jsonb_typeof(input->'product_key') IS DISTINCT FROM 'string')) OR NOT (input ? 'content_digest') OR (input ? 'content_digest' AND (jsonb_typeof(input->'content_digest') IS DISTINCT FROM 'string')) OR (input ? 'content_digest' AND input->>'content_digest' !~ '^[0-9a-f]{64}$') THEN RAISE EXCEPTION 'parsing record shape differs: PdfProductInput' USING ERRCODE='23514'; END IF;

  SELECT * INTO STRICT pin FROM ops.pdf_product WHERE task_id=(input->>'task_id')::bigint AND product_key=input->>'product_key' AND content_digest=input->>'content_digest';
  IF pin.task_id=p_task AND pin.product_key=product->>'product_key' THEN RAISE EXCEPTION 'self PDF input' USING ERRCODE='23514'; END IF;
  IF pin.artifact_digest<>original OR NOT EXISTS(SELECT FROM ops.task t JOIN ops.run r ON r.id=t.run_id WHERE t.id=pin.task_id AND r.project_id=run.project_id) THEN RAISE EXCEPTION 'PDF input outside original/project custody' USING ERRCODE='23514'; END IF;
  IF (input->>'role'='recognition' AND pin.kind<>'recognition_observation') OR (input->>'role'='structural' AND pin.kind NOT IN ('native','integrated')) THEN RAISE EXCEPTION 'PDF input role/kind differs' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT FROM sem.input WHERE release_id=pin.release_id AND input_kind='dependency' AND input_name='execution/schema/pdf_products' AND encode(sha256(content),'hex')=pin.contract_digest) OR
   (pin.kind='native' AND NOT EXISTS(SELECT FROM ops.native_document_product b WHERE b.task_id=pin.task_id AND b.product_key=pin.product_key AND b.content_digest=pin.content_digest)) OR
   (pin.kind<>'native' AND NOT EXISTS(SELECT FROM ops.pdf_product_body b WHERE b.task_id=pin.task_id AND b.product_key=pin.product_key AND encode(sha256(b.payload),'hex')=pin.content_digest)) THEN RAISE EXCEPTION 'PDF input has no admitted immutable body' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM json_array_elements(input_rows))<>(SELECT count(DISTINCT (value->>'role',value->>'task_id',value->>'product_key')) FROM json_array_elements(input_rows)) THEN RAISE EXCEPTION 'duplicate PDF input role/pin' USING ERRCODE='23514'; END IF;
 IF product->>'kind'='recognition_observation' THEN
  IF NOT product ? 'observation' OR 'content'=ANY(envelope_fields) THEN RAISE EXCEPTION 'observation body differs' USING ERRCODE='23514'; END IF;
  IF product->'observation'->'image'->>'precision' NOT IN ('unknown','coarse') OR (product->'observation'->'image'->'transform'->>'status') NOT IN ('unknown','coarse') OR jsonb_typeof((product->'observation'->'binding'->>'decoding_json')::jsonb) IS DISTINCT FROM 'object' OR (product->'observation' ? 'usage_json' AND jsonb_typeof((product->'observation'->>'usage_json')::jsonb) IS DISTINCT FROM 'object') THEN RAISE EXCEPTION 'unadmitted provider transform/precision/settings' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT FROM unnest(p_artifacts) supplied(content) WHERE encode(sha256(supplied.content),'hex')=product->'observation'->'image'->>'artifact_digest' AND octet_length(supplied.content)>=24 AND substring(supplied.content FROM 1 FOR 8)=decode('89504e470d0a1a0a','hex') AND get_byte(supplied.content,16)::bigint*16777216+get_byte(supplied.content,17)::bigint*65536+get_byte(supplied.content,18)::bigint*256+get_byte(supplied.content,19)::bigint=(product->'observation'->'image'->>'width')::bigint AND get_byte(supplied.content,20)::bigint*16777216+get_byte(supplied.content,21)::bigint*65536+get_byte(supplied.content,22)::bigint*256+get_byte(supplied.content,23)::bigint=(product->'observation'->'image'->>'height')::bigint) THEN RAISE EXCEPTION 'submitted PNG dimensions/bytes differ' USING ERRCODE='23514'; END IF;
  IF (product->'observation'->>'outcome' IN ('succeeded','partial') AND NOT product->'observation' ? 'raw_response_digest') OR (product->'observation'->>'outcome' IN ('failed','unknown','unsupported') AND COALESCE(product->'observation'->>'diagnostic','')='') OR product->'health'->>'execution_outcome' IS DISTINCT FROM product->'observation'->>'outcome' OR (product->'observation'->>'usage_availability'='available') IS DISTINCT FROM (product->'observation' ? 'usage_json') THEN RAISE EXCEPTION 'observation response/diagnostic/usage availability differs' USING ERRCODE='23514'; END IF;
  IF product->'observation'->'image'->'transform'->>'status'='unknown' AND product->'observation'->'image'->'transform' ?| ARRAY['page_width','page_height','page_rotation','crop_left','crop_top','crop_right','crop_bottom','affine'] THEN RAISE EXCEPTION 'unknown transform carries fabricated parameters' USING ERRCODE='23514'; END IF;
  IF product->'observation'->'image'->'transform'->>'status'='coarse' AND (NOT product->'observation'->'image'->'transform' ?& ARRAY['page_width','page_height','page_rotation','crop_left','crop_top','crop_right','crop_bottom','affine'] OR jsonb_array_length(product->'observation'->'image'->'transform'->'affine')<>6 OR EXISTS(SELECT FROM jsonb_array_elements(product->'observation'->'image'->'transform'->'affine') WHERE jsonb_typeof(value)<>'number') OR (product->'observation'->'image'->'transform'->>'page_rotation')::bigint NOT IN (0,90,180,270) OR NOT (0<=(product->'observation'->'image'->'transform'->>'crop_left')::numeric AND (product->'observation'->'image'->'transform'->>'crop_left')::numeric<(product->'observation'->'image'->'transform'->>'crop_right')::numeric AND (product->'observation'->'image'->'transform'->>'crop_right')::numeric<=(product->'observation'->'image'->'transform'->>'page_width')::numeric AND 0<=(product->'observation'->'image'->'transform'->>'crop_top')::numeric AND (product->'observation'->'image'->'transform'->>'crop_top')::numeric<(product->'observation'->'image'->'transform'->>'crop_bottom')::numeric AND (product->'observation'->'image'->'transform'->>'crop_bottom')::numeric<=(product->'observation'->'image'->'transform'->>'page_height')::numeric)) THEN RAISE EXCEPTION 'coarse transform requires complete page/crop/rotation witness' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT FROM unnest(ARRAY[product->'observation'->'image'->>'artifact_digest',product->'observation'->>'raw_response_digest']) d WHERE d IS NOT NULL AND NOT EXISTS(SELECT FROM unnest(p_artifacts) content WHERE encode(sha256(content),'hex')=d)) THEN RAISE EXCEPTION 'observation image/raw response bytes are missing' USING ERRCODE='23514'; END IF;
 ELSE
  IF NOT ('content'=ANY(envelope_fields)) OR product ? 'observation' OR NOT EXISTS(SELECT FROM json_array_elements(input_rows) WHERE value->>'role'='structural') OR NOT EXISTS(SELECT FROM json_array_elements(input_rows) WHERE value->>'role'='recognition') THEN RAISE EXCEPTION 'integrated content/input kinds differ' USING ERRCODE='23514'; END IF;
  IF selected_content->>'artifact_digest' IS DISTINCT FROM original OR selected_content->>'recipe_digest' IS DISTINCT FROM product->>'recipe_digest' OR NOT EXISTS(SELECT FROM sem.input WHERE release_id=run.release_id AND input_name='execution/implementation/pdf/docling-validation.schema.json' AND encode(sha256(content),'hex')=selected_content->>'schema_digest') THEN RAISE EXCEPTION 'selected Docling schema/original/recipe custody differs' USING ERRCODE='23514'; END IF;
  IF (selected_content->>'source_scope'='page_range' AND (selected_content->>'page_start' IS NULL OR selected_content->>'page_end' IS NULL OR (selected_content->>'page_start')::bigint>(selected_content->>'page_end')::bigint)) OR (selected_content->>'source_scope'='whole_document' AND (selected_content ? 'page_start' OR selected_content ? 'page_end')) THEN RAISE EXCEPTION 'selected native source scope differs' USING ERRCODE='23514'; END IF;
   -- Compare the complete access universe, not only whichever rows the caller supplied.
 IF EXISTS(
 WITH RECURSIVE nodes AS (
  SELECT '#/'||field.key||'/'||(entry.n-1)::text pointer,entry.value node FROM jsonb_each(selected_document) field
  CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(field.value)='array' THEN field.value ELSE '[]'::jsonb END) WITH ORDINALITY entry(value,n)
  WHERE entry.value ? 'self_ref'
  UNION ALL SELECT selected_document->'body'->>'self_ref',selected_document->'body'
  UNION ALL SELECT selected_document->'furniture'->>'self_ref',selected_document->'furniture'
 ), bad_child_edges AS (
  SELECT edge_parent.pointer FROM nodes edge_parent
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(edge_parent.node->'children','[]'::jsonb)) child
  LEFT JOIN nodes edge_target ON edge_target.pointer=child->>'$ref'
  WHERE edge_target.pointer IS NULL OR edge_target.node->'parent'->>'$ref' IS DISTINCT FROM edge_parent.pointer
 ), walk(pointer,path,trail,scope) AS (
  SELECT pointer,ARRAY[CASE pointer WHEN '#/body' THEN 0 ELSE 1 END]::bigint[],ARRAY[pointer]::text[],NULL::text FROM nodes WHERE pointer IN ('#/body','#/furniture')
  UNION ALL
  SELECT child->>'$ref',w.path||n,w.trail||(child->>'$ref'),CASE WHEN target.node->>'label' IN ('section','chapter') THEN target.pointer ELSE w.scope END
  FROM walk w JOIN nodes parent_node ON parent_node.pointer=w.pointer
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(parent_node.node->'children','[]'::jsonb)) WITH ORDINALITY entry(child,n)
  JOIN nodes target ON target.pointer=child->>'$ref'
  WHERE NOT (child->>'$ref')=ANY(w.trail)
 ), ordered AS (
  SELECT pointer,path,scope FROM walk
  UNION ALL SELECT pointer,ARRAY[2]::bigint[],NULL::text FROM nodes WHERE NOT EXISTS(SELECT FROM walk WHERE walk.pointer=nodes.pointer)
 ), expected AS (
  SELECT nodes.*,row_number() OVER(ORDER BY ordered.path,nodes.pointer)-1 ordinal,ordered.scope
  FROM nodes JOIN ordered USING(pointer)
 )
 SELECT FROM expected e FULL JOIN (SELECT i.pointer,i.ordinal,i.content_layer,i.label,i.text,i.parent_pointer,i.section_pointer,selected_document #> string_to_array(substr(i.pointer,3),'/') native_json FROM jsonb_populate_recordset(NULL::kb.native_document_item,selected_content->'items') i) actual USING(pointer)
 WHERE e.pointer IS NULL OR actual.pointer IS NULL OR actual.ordinal IS DISTINCT FROM e.ordinal
 OR actual.content_layer IS DISTINCT FROM e.node->>'content_layer'
 OR e.node->>'self_ref' IS DISTINCT FROM e.pointer
 OR actual.label IS DISTINCT FROM e.node->>'label'
 OR actual.text IS DISTINCT FROM e.node->>'text'
 OR actual.native_json IS DISTINCT FROM e.node
 OR actual.parent_pointer IS DISTINCT FROM e.node->'parent'->>'$ref'
 OR (actual.parent_pointer IS NOT NULL AND NOT EXISTS(SELECT FROM nodes p WHERE p.pointer=actual.parent_pointer))
 OR actual.section_pointer IS DISTINCT FROM e.scope
 OR EXISTS(SELECT FROM bad_child_edges)
 ) THEN RAISE EXCEPTION 'native access universe/order/membership differs' USING ERRCODE='23514'; END IF;
 -- One set-shaped provenance projection avoids repeated whole-document pointer lookup.
 IF EXISTS(
 WITH nodes AS (
  SELECT entry.value node FROM jsonb_each(selected_document) field
  CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(field.value)='array' THEN field.value ELSE '[]'::jsonb END) entry(value)
  WHERE entry.value ? 'self_ref'
 ), expected AS (
  SELECT node->>'self_ref' pointer,n-1 region_index,prov,
   selected_document->'pages'->(prov->>'page_no')->'size' page_size
  FROM nodes CROSS JOIN LATERAL jsonb_array_elements(COALESCE(node->'prov','[]'::jsonb)) WITH ORDINALITY regions(prov,n)
 )
 SELECT FROM expected e FULL JOIN (SELECT * FROM jsonb_populate_recordset(NULL::kb.native_document_region,selected_content->'regions')) r USING(pointer,region_index)
 WHERE e.pointer IS NULL OR r.pointer IS NULL
 OR (e.prov->>'page_no')::bigint IS DISTINCT FROM r.page_no
 OR (e.page_size->>'width')::numeric IS DISTINCT FROM r.page_width
 OR (e.page_size->>'height')::numeric IS DISTINCT FROM r.page_height
 OR (e.prov->'bbox'->>'l')::numeric IS DISTINCT FROM r."left"
 OR (e.prov->'bbox'->>'t')::numeric IS DISTINCT FROM r.top
 OR (e.prov->'bbox'->>'r')::numeric IS DISTINCT FROM r."right"
 OR (e.prov->'bbox'->>'b')::numeric IS DISTINCT FROM r.bottom
 OR CASE e.prov->'bbox'->>'coord_origin' WHEN 'TOPLEFT' THEN 'top_left' WHEN 'BOTTOMLEFT' THEN 'bottom_left' END IS DISTINCT FROM r.origin
 ) THEN RAISE EXCEPTION 'native region projection differs' USING ERRCODE='23514'; END IF;

 END IF;
 IF NOT EXISTS(SELECT FROM unnest(p_artifacts) content WHERE encode(sha256(content),'hex')=product->>'recipe_digest') THEN RAISE EXCEPTION 'PDF recipe bytes are missing' USING ERRCODE='23514'; END IF;
 INSERT INTO kb.source_artifact(artifact_digest,content) SELECT encode(sha256(content),'hex'),content FROM unnest(p_artifacts) content ON CONFLICT DO NOTHING;
 INSERT INTO ops.pdf_product(task_id,product_key,content_digest,kind,artifact_digest,release_id,contract_digest) VALUES(p_task,product->>'product_key',digest,product->>'kind',original,run.release_id,p_contract);
 IF product->>'kind'='integrated' THEN
  INSERT INTO kb.native_document_item(task_id,product_key,pointer,ordinal,label,parent_pointer,section_pointer,content_layer,text,native_json)
  SELECT p_task,product->>'product_key',i.pointer,i.ordinal,i.label,i.parent_pointer,i.section_pointer,i.content_layer,i.text,selected_document #> string_to_array(substr(i.pointer,3),'/') FROM jsonb_populate_recordset(NULL::kb.native_document_item,selected_content->'items') i;
  INSERT INTO kb.native_document_region(task_id,product_key,pointer,region_index,page_no,page_width,page_height,"left",top,"right",bottom,origin)
  SELECT p_task,product->>'product_key',r.pointer,r.region_index,r.page_no,r.page_width,r.page_height,r."left",r.top,r."right",r.bottom,r.origin FROM jsonb_populate_recordset(NULL::kb.native_document_region,selected_content->'regions') r;
 END IF;
 INSERT INTO ops.pdf_product_artifact(task_id,product_key,artifact_digest) SELECT p_task,product->>'product_key',encode(sha256(supplied.content),'hex') FROM unnest(p_artifacts) supplied(content) ON CONFLICT DO NOTHING;
 INSERT INTO ops.pdf_product_body(task_id,product_key,payload,recipe_digest,descriptor) VALUES(p_task,product->>'product_key',p_payload,product->>'recipe_digest',product||CASE WHEN product->>'kind'='integrated' THEN jsonb_build_object('content_metadata',jsonb_build_object('schema_digest',selected_content->'schema_digest','recipe_digest',selected_content->'recipe_digest','health',selected_content->'health')) ELSE '{}'::jsonb END);
 INSERT INTO ops.pdf_product_input(task_id,product_key,input_index,role,input_task_id,input_product_key,input_content_digest)
 SELECT p_task,product->>'product_key',n-1,value->>'role',(value->>'task_id')::bigint,value->>'product_key',value->>'content_digest' FROM json_array_elements(input_rows) WITH ORDINALITY i(value,n);
 FOR occurrence IN SELECT value::jsonb FROM json_array_elements(occurrence_rows) LOOP
  IF jsonb_typeof(occurrence) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfProductOccurrence' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(occurrence) key WHERE key<>ALL(ARRAY['occurrence_id','kind','address_space','precision','pointer','grounding_pointer','region_index','cell_index','page_no','text','start','end','region'])) OR NOT (occurrence ? 'occurrence_id') OR (occurrence ? 'occurrence_id' AND (jsonb_typeof(occurrence->'occurrence_id') IS DISTINCT FROM 'string')) OR NOT (occurrence ? 'kind') OR (occurrence ? 'kind' AND (jsonb_typeof(occurrence->'kind') IS DISTINCT FROM 'string' OR occurrence->>'kind' NOT IN ('cell','chart','formula','item','region','text'))) OR NOT (occurrence ? 'address_space') OR (occurrence ? 'address_space' AND (jsonb_typeof(occurrence->'address_space') IS DISTINCT FROM 'string' OR occurrence->>'address_space' NOT IN ('analytical_projection','native_cell','native_item','normalized_raw','pdf_points','raw_response','recognized_text','selected_item','submitted_pixels'))) OR NOT (occurrence ? 'precision') OR (occurrence ? 'precision' AND (jsonb_typeof(occurrence->'precision') IS DISTINCT FROM 'string' OR occurrence->>'precision' NOT IN ('block','cell','coarse','glyph','inherited','item','unknown','word'))) OR (occurrence ? 'pointer' AND (jsonb_typeof(occurrence->'pointer') IS DISTINCT FROM 'string')) OR (occurrence ? 'pointer' AND occurrence->>'pointer' !~ '^#(/[^/]+)+$') OR (occurrence ? 'grounding_pointer' AND (jsonb_typeof(occurrence->'grounding_pointer') IS DISTINCT FROM 'string')) OR (occurrence ? 'grounding_pointer' AND occurrence->>'grounding_pointer' !~ '^#(/[^/]+)+$') OR (occurrence ? 'region_index' AND (jsonb_typeof(occurrence->'region_index') IS DISTINCT FROM 'number' OR occurrence->>'region_index' !~ '^[0-9]+$')) OR (occurrence ? 'region_index' AND (occurrence->>'region_index')::numeric < 0) OR (occurrence ? 'cell_index' AND (jsonb_typeof(occurrence->'cell_index') IS DISTINCT FROM 'number' OR occurrence->>'cell_index' !~ '^[0-9]+$')) OR (occurrence ? 'cell_index' AND (occurrence->>'cell_index')::numeric < 0) OR (occurrence ? 'page_no' AND (jsonb_typeof(occurrence->'page_no') IS DISTINCT FROM 'number' OR occurrence->>'page_no' !~ '^[0-9]+$')) OR (occurrence ? 'page_no' AND (occurrence->>'page_no')::numeric < 1) OR (occurrence ? 'text' AND (jsonb_typeof(occurrence->'text') IS DISTINCT FROM 'string')) OR (occurrence ? 'start' AND (jsonb_typeof(occurrence->'start') IS DISTINCT FROM 'number' OR occurrence->>'start' !~ '^[0-9]+$')) OR (occurrence ? 'start' AND (occurrence->>'start')::numeric < 0) OR (occurrence ? 'end' AND (jsonb_typeof(occurrence->'end') IS DISTINCT FROM 'number' OR occurrence->>'end' !~ '^[0-9]+$')) OR (occurrence ? 'end' AND (occurrence->>'end')::numeric < 0) OR (occurrence ? 'region' AND (jsonb_typeof(occurrence->'region') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(occurrence->'region') key WHERE key<>ALL(ARRAY['address_space','precision','normalization','origin','left','top','right','bottom'])) OR NOT (occurrence->'region' ? 'address_space') OR (occurrence->'region' ? 'address_space' AND (jsonb_typeof(occurrence->'region'->'address_space') IS DISTINCT FROM 'string' OR occurrence->'region'->>'address_space' NOT IN ('analytical_projection','native_cell','native_item','normalized_raw','pdf_points','raw_response','recognized_text','selected_item','submitted_pixels'))) OR NOT (occurrence->'region' ? 'precision') OR (occurrence->'region' ? 'precision' AND (jsonb_typeof(occurrence->'region'->'precision') IS DISTINCT FROM 'string' OR occurrence->'region'->>'precision' NOT IN ('block','cell','coarse','glyph','inherited','item','unknown','word'))) OR NOT (occurrence->'region' ? 'normalization') OR (occurrence->'region' ? 'normalization' AND (jsonb_typeof(occurrence->'region'->'normalization') IS DISTINCT FROM 'string' OR occurrence->'region'->>'normalization' NOT IN ('clipped','inherited','none','normalized','unknown'))) OR NOT (occurrence->'region' ? 'origin') OR (occurrence->'region' ? 'origin' AND (jsonb_typeof(occurrence->'region'->'origin') IS DISTINCT FROM 'string' OR occurrence->'region'->>'origin' NOT IN ('bottom_left','top_left'))) OR NOT (occurrence->'region' ? 'left') OR (occurrence->'region' ? 'left' AND (jsonb_typeof(occurrence->'region'->'left') IS DISTINCT FROM 'number')) OR NOT (occurrence->'region' ? 'top') OR (occurrence->'region' ? 'top' AND (jsonb_typeof(occurrence->'region'->'top') IS DISTINCT FROM 'number')) OR NOT (occurrence->'region' ? 'right') OR (occurrence->'region' ? 'right' AND (jsonb_typeof(occurrence->'region'->'right') IS DISTINCT FROM 'number')) OR NOT (occurrence->'region' ? 'bottom') OR (occurrence->'region' ? 'bottom' AND (jsonb_typeof(occurrence->'region'->'bottom') IS DISTINCT FROM 'number'))))) THEN RAISE EXCEPTION 'parsing record shape differs: PdfProductOccurrence' USING ERRCODE='23514'; END IF;

  IF occurrence->>'occurrence_id'='' OR ((occurrence ? 'start')<>(occurrence ? 'end')) OR (occurrence ? 'start' AND ((occurrence->>'start')::bigint>(occurrence->>'end')::bigint OR occurrence->>'address_space' NOT IN ('native_item','recognized_text','selected_item','raw_response') OR occurrence->>'precision' IN ('unknown','coarse','block','inherited') OR (occurrence ? 'text' AND (occurrence->>'end')::bigint>char_length(occurrence->>'text')))) THEN RAISE EXCEPTION 'unqualified PDF occurrence address/range' USING ERRCODE='23514'; END IF;
  IF occurrence ? 'region' AND ((occurrence->'region'->>'left')::numeric>(occurrence->'region'->>'right')::numeric OR (occurrence->'region'->>'origin'='top_left' AND (occurrence->'region'->>'top')::numeric>(occurrence->'region'->>'bottom')::numeric) OR (occurrence->'region'->>'origin'='bottom_left' AND (occurrence->'region'->>'top')::numeric<(occurrence->'region'->>'bottom')::numeric)) THEN RAISE EXCEPTION 'region coordinate origin/bounds differ' USING ERRCODE='23514'; END IF;
  IF product->>'kind'='recognition_observation' AND occurrence ? 'region' AND (occurrence->'region'->>'precision' NOT IN ('unknown','coarse','block') OR occurrence->'region'->>'address_space' NOT IN ('submitted_pixels','normalized_raw') OR (occurrence->'region'->>'address_space'='submitted_pixels' AND (occurrence->'region'->>'origin'<>'top_left' OR (occurrence->'region'->>'left')::numeric<0 OR (occurrence->'region'->>'right')::numeric>(product->'observation'->'image'->>'width')::numeric OR (occurrence->'region'->>'top')::numeric<0 OR (occurrence->'region'->>'bottom')::numeric>(product->'observation'->'image'->>'height')::numeric)) OR (occurrence->'region'->>'address_space'='normalized_raw' AND EXISTS(SELECT FROM jsonb_each(occurrence->'region') entry WHERE entry.key IN ('left','top','right','bottom') AND ((entry.value::text)::numeric<0 OR (entry.value::text)::numeric>1)))) THEN RAISE EXCEPTION 'provider region precision/frame/bounds differs' USING ERRCODE='23514'; END IF;
  IF product->>'kind'='recognition_observation' AND occurrence ? 'page_no' AND occurrence->>'page_no' IS DISTINCT FROM product->'observation'->'image'->>'page_no' THEN RAISE EXCEPTION 'observation page differs from submitted image' USING ERRCODE='23514'; END IF;
  IF product->>'kind'='recognition_observation' AND occurrence->>'precision' NOT IN ('unknown','coarse','block') THEN RAISE EXCEPTION 'I10/I11 provider precision is unadmitted' USING ERRCODE='23514'; END IF;
  IF product->>'kind'='integrated' THEN
   IF NOT occurrence ? 'pointer' THEN RAISE EXCEPTION 'selected occurrence has no native pointer' USING ERRCODE='23514'; END IF;
   selected_node:=selected_document #> string_to_array(substr(occurrence->>'pointer',3),'/');
   selected_anchor:=selected_node; grounding_path:=ARRAY[occurrence->>'pointer'];
   IF occurrence ? 'grounding_pointer' THEN
    IF occurrence->>'precision'<>'inherited' OR occurrence->'region'->>'precision'<>'inherited' OR occurrence->>'kind'='region' THEN RAISE EXCEPTION 'inherited grounding requires inherited precision' USING ERRCODE='23514'; END IF;
    IF occurrence->>'grounding_pointer'<>occurrence->>'pointer' AND jsonb_array_length(COALESCE(selected_node->'prov','[]'))>0 THEN RAISE EXCEPTION 'boxed occurrence cannot replace own witness' USING ERRCODE='23514'; END IF;
    WHILE selected_anchor->>'self_ref' IS DISTINCT FROM occurrence->>'grounding_pointer' LOOP
     ancestor_pointer:=selected_anchor->'parent'->>'$ref';
     IF ancestor_pointer IS NULL OR ancestor_pointer=ANY(grounding_path) THEN RAISE EXCEPTION 'grounding is not an ancestor' USING ERRCODE='23514'; END IF;
     grounding_path:=array_append(grounding_path,ancestor_pointer);
     selected_anchor:=selected_document #> string_to_array(substr(ancestor_pointer,3),'/');
    END LOOP;
   END IF;
   IF occurrence->>'kind'='cell' THEN
    IF NOT occurrence ? 'cell_index' OR selected_node->>'label' NOT IN ('table','picture') THEN RAISE EXCEPTION 'selected cell is outside native table/chart' USING ERRCODE='23514'; END IF;
    IF selected_node->>'label'='picture' AND occurrence->>'precision'<>'inherited' THEN RAISE EXCEPTION 'chart cell requires inherited chart witness' USING ERRCODE='23514'; END IF;
    selected_node:=CASE selected_node->>'label' WHEN 'table' THEN selected_node->'data'->'table_cells' ELSE selected_node->'meta'->'tabular_chart'->'chart_data'->'table_cells' END -> ((occurrence->>'cell_index')::integer);
   ELSIF occurrence ? 'cell_index' THEN RAISE EXCEPTION 'cell index requires a cell occurrence' USING ERRCODE='23514'; END IF;
   IF selected_node IS NULL OR (occurrence ? 'text' AND occurrence->>'text' IS DISTINCT FROM selected_node->>'text') THEN RAISE EXCEPTION 'selected occurrence differs from native content' USING ERRCODE='23514'; END IF;
   IF (occurrence->>'kind'='cell' AND (occurrence->>'address_space'<>'native_cell' OR occurrence->>'precision' NOT IN ('cell','item','inherited','coarse','unknown'))) OR (occurrence->>'kind'<>'cell' AND (occurrence->>'kind' NOT IN ('item','text','formula','chart','region') OR (occurrence->>'kind'<>'region' AND (occurrence->>'kind'='formula') IS DISTINCT FROM (selected_node->>'label'='formula')) OR (occurrence->>'kind'='chart' AND (selected_node->>'label' IS DISTINCT FROM 'picture' OR NOT (selected_node->'meta' ? 'tabular_chart' OR EXISTS(SELECT FROM jsonb_array_elements(COALESCE(selected_node->'annotations','[]')) WHERE value->>'kind' LIKE '%\_chart_data' ESCAPE '\')))) OR (occurrence->>'kind'='text' AND selected_node->>'label'<>'text') OR (occurrence->>'address_space' NOT IN ('native_item','selected_item') AND NOT (occurrence->>'kind'='region' AND occurrence->>'address_space'='pdf_points')) OR occurrence->>'precision' NOT IN ('item','inherited','coarse','unknown'))) OR (occurrence ? 'start' AND NOT occurrence ? 'text') THEN RAISE EXCEPTION 'selected kind/address/precision differs from native custody' USING ERRCODE='23514'; END IF;
   IF occurrence ? 'page_no' AND NOT EXISTS(SELECT FROM jsonb_array_elements(COALESCE(selected_anchor->'prov','[]')) WHERE value->>'page_no'=occurrence->>'page_no') THEN RAISE EXCEPTION 'selected page differs from native provenance' USING ERRCODE='23514'; END IF;
   IF (occurrence->>'kind'='region' AND (NOT occurrence ? 'region_index' OR NOT occurrence ? 'region' OR (occurrence->>'region_index')::bigint>=jsonb_array_length(COALESCE(selected_node->'prov','[]')))) OR (occurrence->>'kind'<>'region' AND occurrence ? 'region_index') THEN RAISE EXCEPTION 'native region index/witness differs' USING ERRCODE='23514'; END IF;
   IF occurrence ? 'region' AND (NOT occurrence ? 'page_no' OR occurrence->'region'->>'address_space'<>'pdf_points' OR occurrence->'region'->>'precision' NOT IN ('cell','item','inherited','coarse','unknown') OR NOT EXISTS(SELECT FROM (
    SELECT value->'bbox' box,value->>'page_no' page FROM jsonb_array_elements(COALESCE(selected_anchor->'prov','[]')) WITH ORDINALITY p(value,n) WHERE occurrence->>'kind'<>'region' OR n-1=(occurrence->>'region_index')::bigint
    UNION ALL SELECT selected_node->'bbox',((selected_document #> string_to_array(substr(occurrence->>'pointer',3),'/'))->'prov'->0->>'page_no') WHERE occurrence->>'kind'='cell' AND selected_node ? 'bbox' AND jsonb_array_length(COALESCE((selected_document #> string_to_array(substr(occurrence->>'pointer',3),'/'))->'prov','[]'))=1
   ) boxes WHERE page=occurrence->>'page_no' AND (occurrence->'region'->>'left')::numeric=(box->>'l')::numeric AND (occurrence->'region'->>'top')::numeric=(box->>'t')::numeric AND (occurrence->'region'->>'right')::numeric=(box->>'r')::numeric AND (occurrence->'region'->>'bottom')::numeric=(box->>'b')::numeric AND occurrence->'region'->>'origin'=CASE box->>'coord_origin' WHEN 'TOPLEFT' THEN 'top_left' WHEN 'BOTTOMLEFT' THEN 'bottom_left' END)) THEN RAISE EXCEPTION 'selected region differs from retained native page/geometry' USING ERRCODE='23514'; END IF;
   occurrence:=occurrence||jsonb_build_object('native_value',selected_node);
  END IF;
  INSERT INTO kb.pdf_occurrence(task_id,product_key,occurrence_id,kind,address_space,precision,body,pointer) VALUES(p_task,product->>'product_key',occurrence->>'occurrence_id',occurrence->>'kind',occurrence->>'address_space',occurrence->>'precision',occurrence,occurrence->>'pointer');
 END LOOP;
 IF product->>'kind'='integrated' AND EXISTS(
 WITH nodes AS (SELECT value node FROM jsonb_each(selected_document) e WHERE key IN ('body','furniture') UNION ALL SELECT entry.value FROM jsonb_each(selected_document) e CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(e.value)='array' THEN e.value ELSE '[]'::jsonb END) entry WHERE entry.value ? 'self_ref'), expected AS (SELECT node->>'self_ref' pointer,NULL::bigint cell_index FROM nodes UNION ALL SELECT node->>'self_ref',n-1 FROM nodes CROSS JOIN LATERAL jsonb_array_elements(COALESCE(CASE node->>'label' WHEN 'table' THEN node->'data'->'table_cells' WHEN 'picture' THEN node->'meta'->'tabular_chart'->'chart_data'->'table_cells' END,'[]')) WITH ORDINALITY c(value,n)), actual AS (SELECT body->>'pointer' pointer,(body->>'cell_index')::bigint cell_index FROM kb.pdf_occurrence WHERE task_id=p_task AND product_key=product->>'product_key' AND kind<>'region') SELECT FROM expected e FULL JOIN actual a ON e.pointer=a.pointer AND e.cell_index IS NOT DISTINCT FROM a.cell_index WHERE e.pointer IS NULL OR a.pointer IS NULL UNION ALL SELECT FROM actual GROUP BY pointer,cell_index HAVING count(*)<>1) THEN RAISE EXCEPTION 'selected content occurrence inventory is incomplete or ambiguous' USING ERRCODE='23514'; END IF;
 FOR relation IN SELECT value::jsonb FROM json_array_elements(relation_rows) LOOP
  IF jsonb_typeof(relation) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfProductRelation' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(relation) key WHERE key<>ALL(ARRAY['relation_id','kind','outcome','comparison','policy','evidence','endpoints'])) OR NOT (relation ? 'relation_id') OR (relation ? 'relation_id' AND (jsonb_typeof(relation->'relation_id') IS DISTINCT FROM 'string')) OR NOT (relation ? 'kind') OR (relation ? 'kind' AND (jsonb_typeof(relation->'kind') IS DISTINCT FROM 'string' OR relation->>'kind' NOT IN ('correspondence','decision'))) OR NOT (relation ? 'outcome') OR (relation ? 'outcome' AND (jsonb_typeof(relation->'outcome') IS DISTINCT FROM 'string')) OR NOT (relation ? 'comparison') OR (relation ? 'comparison' AND (jsonb_typeof(relation->'comparison') IS DISTINCT FROM 'string' OR relation->>'comparison' NOT IN ('geometry','grid','mathematical','order','text'))) OR NOT (relation ? 'policy') OR (relation ? 'policy' AND (jsonb_typeof(relation->'policy') IS DISTINCT FROM 'string')) OR NOT (relation ? 'evidence') OR (relation ? 'evidence' AND (jsonb_typeof(relation->'evidence') IS DISTINCT FROM 'string')) OR NOT (relation ? 'endpoints') OR (relation ? 'endpoints' AND (jsonb_typeof(relation->'endpoints') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(relation->'endpoints') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['role','occurrence_id','input_index'])) OR NOT (nested_record ? 'role') OR (nested_record ? 'role' AND (jsonb_typeof(nested_record->'role') IS DISTINCT FROM 'string' OR nested_record->>'role' NOT IN ('alternative','evidence','input','output'))) OR NOT (nested_record ? 'occurrence_id') OR (nested_record ? 'occurrence_id' AND (jsonb_typeof(nested_record->'occurrence_id') IS DISTINCT FROM 'string')) OR (nested_record ? 'input_index' AND (jsonb_typeof(nested_record->'input_index') IS DISTINCT FROM 'number' OR nested_record->>'input_index' !~ '^[0-9]+$')) OR (nested_record ? 'input_index' AND (nested_record->>'input_index')::numeric < 0))) OR jsonb_array_length(relation->'endpoints') < 1)) THEN RAISE EXCEPTION 'parsing record shape differs: PdfProductRelation' USING ERRCODE='23514'; END IF;

  IF relation->>'relation_id'='' OR relation->>'policy'='' OR relation->>'evidence'='' OR (relation->>'kind'='correspondence' AND relation->>'outcome' NOT IN ('matched','ambiguous','unmatched','unresolved')) OR (relation->>'kind'='decision' AND relation->>'outcome' NOT IN ('selected','added','replaced','retained_alternative','rejected','unresolved')) THEN RAISE EXCEPTION 'PDF relation kind/outcome/policy differs' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(relation->'endpoints') WHERE value ? 'input_index') OR (relation->>'kind'='correspondence' AND relation->>'outcome' IN ('matched','ambiguous') AND (SELECT count(DISTINCT (value->>'input_index',value->>'occurrence_id')) FROM jsonb_array_elements(relation->'endpoints'))<2) OR (relation->>'kind'='decision' AND relation->>'outcome' IN ('selected','added','replaced') AND NOT EXISTS(SELECT FROM jsonb_array_elements(relation->'endpoints') WHERE value->>'role'='output')) OR (relation->>'kind'='decision' AND relation->>'outcome'='rejected' AND EXISTS(SELECT FROM jsonb_array_elements(relation->'endpoints') WHERE value->>'role'='output')) THEN RAISE EXCEPTION 'PDF relation endpoint set differs' USING ERRCODE='23514'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(relation->'endpoints'))<>(SELECT count(DISTINCT (value->>'input_index',value->>'occurrence_id',value->>'role')) FROM jsonb_array_elements(relation->'endpoints')) THEN RAISE EXCEPTION 'duplicate PDF relation endpoint' USING ERRCODE='23514'; END IF;
  INSERT INTO kb.pdf_relation(task_id,product_key,relation_id,kind,body) VALUES(p_task,product->>'product_key',relation->>'relation_id',relation->>'kind',relation-'endpoints');
  FOR endpoint,eid IN SELECT value,n-1 FROM jsonb_array_elements(relation->'endpoints') WITH ORDINALITY e(value,n) LOOP
   IF endpoint ? 'input_index' THEN
    SELECT p.* INTO pin FROM ops.pdf_product_input i JOIN ops.pdf_product p
      ON (p.task_id,p.product_key,p.content_digest)=(i.input_task_id,i.input_product_key,i.input_content_digest)
      WHERE i.task_id=p_task AND i.product_key=product->>'product_key' AND i.input_index=(endpoint->>'input_index')::bigint;
    IF NOT FOUND OR endpoint->>'role'='output' THEN RAISE EXCEPTION 'PDF endpoint input index/role differs' USING ERRCODE='23514'; END IF;
   ELSE
    IF endpoint->>'role'<>'output' THEN RAISE EXCEPTION 'local PDF endpoint must be output' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT pin FROM ops.pdf_product WHERE task_id=p_task AND product_key=product->>'product_key';
   END IF;
   INSERT INTO kb.pdf_relation_endpoint(task_id,product_key,relation_id,endpoint_index,role,target_task_id,target_product_key,target_content_digest,occurrence_id) VALUES(p_task,product->>'product_key',relation->>'relation_id',eid,endpoint->>'role',pin.task_id,pin.product_key,pin.content_digest,endpoint->>'occurrence_id');
  END LOOP;
 END LOOP;
 IF product->>'kind'='integrated' AND EXISTS(SELECT FROM kb.pdf_occurrence o WHERE o.task_id=p_task AND o.product_key=product->>'product_key' AND NOT EXISTS(SELECT FROM kb.pdf_relation r JOIN kb.pdf_relation_endpoint e USING(task_id,product_key,relation_id) WHERE r.task_id=o.task_id AND r.product_key=o.product_key AND r.kind='decision' AND r.body->>'outcome' IN ('selected','added','replaced') AND e.role='output' AND e.occurrence_id=o.occurrence_id)) THEN RAISE EXCEPTION 'selected occurrence lacks governing integration decision' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM (SELECT value::jsonb AS r FROM json_array_elements(COALESCE(mapping_rows,'[]'::json))) reports LEFT JOIN ops.pdf_product_input i ON i.task_id=p_task AND i.product_key=product->>'product_key' AND i.input_index=(r->>'input_index')::bigint WHERE i.role IS DISTINCT FROM 'recognition' OR (r->>'outcome'<>'mapped' AND COALESCE(r->>'reason','')='') OR (r ? 'occurrence_id' AND NOT EXISTS(SELECT FROM kb.pdf_occurrence o WHERE o.task_id=i.input_task_id AND o.product_key=i.input_product_key AND o.occurrence_id=r->>'occurrence_id'))) THEN RAISE EXCEPTION 'mapping disposition differs from recognition custody' USING ERRCODE='23514'; END IF;
 FOR mapping_report,idx IN SELECT value::jsonb,n-1 FROM json_array_elements(COALESCE(mapping_rows,'[]'::json)) WITH ORDINALITY rows(value,n) LOOP
  IF jsonb_typeof(mapping_report) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfMappingDisposition' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(mapping_report) key WHERE key<>ALL(ARRAY['input_index','occurrence_id','outcome','label','reason','raw_start','coordinate_frame','coordinate_scale','normalization'])) OR NOT (mapping_report ? 'input_index') OR (mapping_report ? 'input_index' AND (jsonb_typeof(mapping_report->'input_index') IS DISTINCT FROM 'number' OR mapping_report->>'input_index' !~ '^[0-9]+$')) OR (mapping_report ? 'input_index' AND (mapping_report->>'input_index')::numeric < 0) OR (mapping_report ? 'occurrence_id' AND (jsonb_typeof(mapping_report->'occurrence_id') IS DISTINCT FROM 'string')) OR NOT (mapping_report ? 'outcome') OR (mapping_report ? 'outcome' AND (jsonb_typeof(mapping_report->'outcome') IS DISTINCT FROM 'string' OR mapping_report->>'outcome' NOT IN ('dropped','evidence_only','mapped','unresolved','unsupported'))) OR (mapping_report ? 'label' AND (jsonb_typeof(mapping_report->'label') IS DISTINCT FROM 'string')) OR (mapping_report ? 'reason' AND (jsonb_typeof(mapping_report->'reason') IS DISTINCT FROM 'string')) OR (mapping_report ? 'raw_start' AND (jsonb_typeof(mapping_report->'raw_start') IS DISTINCT FROM 'number' OR mapping_report->>'raw_start' !~ '^[0-9]+$')) OR (mapping_report ? 'raw_start' AND (mapping_report->>'raw_start')::numeric < 0) OR (mapping_report ? 'coordinate_frame' AND (jsonb_typeof(mapping_report->'coordinate_frame') IS DISTINCT FROM 'string')) OR (mapping_report ? 'coordinate_scale' AND (jsonb_typeof(mapping_report->'coordinate_scale') IS DISTINCT FROM 'number')) OR (mapping_report ? 'coordinate_scale' AND (mapping_report->>'coordinate_scale')::numeric < 1) OR (mapping_report ? 'normalization' AND (jsonb_typeof(mapping_report->'normalization') IS DISTINCT FROM 'string' OR mapping_report->>'normalization' NOT IN ('clipped','inherited','none','normalized','unknown'))) THEN RAISE EXCEPTION 'parsing record shape differs: PdfMappingDisposition' USING ERRCODE='23514'; END IF;

  INSERT INTO kb.pdf_mapping_report(task_id,product_key,report_index,input_index,body)
  VALUES(p_task,product->>'product_key',idx,(mapping_report->>'input_index')::bigint,mapping_report);
 END LOOP;
 IF json_array_length(coverage_rows)=0 THEN RAISE EXCEPTION 'PDF coverage is mandatory' USING ERRCODE='23514'; END IF;
 FOR coverage IN SELECT value::jsonb FROM json_array_elements(coverage_rows) LOOP
  IF jsonb_typeof(coverage) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfProductCoverage' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(coverage) key WHERE key<>ALL(ARRAY['coverage_id','scope','family','discovery_policy','outcome','detail','supports'])) OR NOT (coverage ? 'coverage_id') OR (coverage ? 'coverage_id' AND (jsonb_typeof(coverage->'coverage_id') IS DISTINCT FROM 'string')) OR NOT (coverage ? 'scope') OR (coverage ? 'scope' AND (jsonb_typeof(coverage->'scope') IS DISTINCT FROM 'string')) OR NOT (coverage ? 'family') OR (coverage ? 'family' AND (jsonb_typeof(coverage->'family') IS DISTINCT FROM 'string')) OR NOT (coverage ? 'discovery_policy') OR (coverage ? 'discovery_policy' AND (jsonb_typeof(coverage->'discovery_policy') IS DISTINCT FROM 'string')) OR NOT (coverage ? 'outcome') OR (coverage ? 'outcome' AND (jsonb_typeof(coverage->'outcome') IS DISTINCT FROM 'string' OR coverage->>'outcome' NOT IN ('capped','complete','partial','unknown','unrequested','unsupported'))) OR NOT (coverage ? 'detail') OR (coverage ? 'detail' AND (jsonb_typeof(coverage->'detail') IS DISTINCT FROM 'string')) OR (coverage ? 'supports' AND (jsonb_typeof(coverage->'supports') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(coverage->'supports') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['input_index','coverage_id'])) OR NOT (nested_record ? 'input_index') OR (nested_record ? 'input_index' AND (jsonb_typeof(nested_record->'input_index') IS DISTINCT FROM 'number' OR nested_record->>'input_index' !~ '^[0-9]+$')) OR (nested_record ? 'input_index' AND (nested_record->>'input_index')::numeric < 0) OR NOT (nested_record ? 'coverage_id') OR (nested_record ? 'coverage_id' AND (jsonb_typeof(nested_record->'coverage_id') IS DISTINCT FROM 'string')))))) THEN RAISE EXCEPTION 'parsing record shape differs: PdfProductCoverage' USING ERRCODE='23514'; END IF;

  IF coverage->>'coverage_id'='' OR coverage->>'scope'='' OR coverage->>'family'='' OR coverage->>'discovery_policy'='' OR coverage->>'detail'='' OR (product->>'kind'='recognition_observation' AND coverage->>'outcome'='complete') THEN RAISE EXCEPTION 'PDF coverage scope/policy/outcome differs' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT FROM jsonb_array_elements(coverage->'supports') support LEFT JOIN ops.pdf_product_input i ON i.task_id=p_task AND i.product_key=product->>'product_key' AND i.input_index=(support->>'input_index')::bigint LEFT JOIN kb.pdf_product_coverage c ON c.task_id=i.input_task_id AND c.product_key=i.input_product_key AND c.coverage_id=support->>'coverage_id' WHERE c.coverage_id IS NULL OR c.body->>'scope' IS DISTINCT FROM coverage->>'scope' OR c.body->>'family' IS DISTINCT FROM coverage->>'family') OR (coverage->>'outcome'='complete' AND NOT EXISTS(SELECT FROM jsonb_array_elements(coverage->'supports') support JOIN ops.pdf_product_input i ON i.task_id=p_task AND i.product_key=product->>'product_key' AND i.input_index=(support->>'input_index')::bigint JOIN kb.pdf_product_coverage c ON c.task_id=i.input_task_id AND c.product_key=i.input_product_key AND c.coverage_id=support->>'coverage_id' WHERE c.body->>'scope'=coverage->>'scope' AND c.body->>'family'=coverage->>'family' AND c.body->>'outcome'='complete')) THEN RAISE EXCEPTION 'complete coverage lacks qualified scope/family input attribution' USING ERRCODE='23514'; END IF;
  INSERT INTO kb.pdf_product_coverage(task_id,product_key,coverage_id,body) VALUES(p_task,product->>'product_key',coverage->>'coverage_id',coverage);
 END LOOP;
 RETURN digest;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.publish_integrated_pdf (bigint, bigint, text, text, bytea, bytea[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.publish_integrated_pdf (bigint, bigint, text, text, bytea, bytea[]) TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION ops.publish_native_document(p_task bigint, p_attempt bigint, p_holder text, p_contract text, p_payload bytea, p_original bytea, p_schema bytea, p_recipe bytea) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE job ops.task; run ops.run; previous ops.native_document_product;
 product jsonb; parsing_item jsonb; digest text; artifact text; parent ops.native_document_product; coverage jsonb;
BEGIN
 SELECT r.* INTO STRICT run FROM ops.run r JOIN ops.task t ON t.run_id=r.id WHERE t.id=p_task FOR SHARE OF r;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=run.id FOR UPDATE;
 IF job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder THEN
  RAISE EXCEPTION 'stale native document attempt' USING ERRCODE='P0004'; END IF;
 product:=convert_from(p_payload,'UTF8')::jsonb; digest:=encode(sha256(p_payload),'hex');
 IF product ? 'document_json' THEN RAISE EXCEPTION 'internal PDF field supplied' USING ERRCODE='23514'; END IF;
parsing_item := (product - 'document') || jsonb_build_object('document_json', (product->'document')::text);
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfNativeEnvelope' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['recipe','source_scope','page_start','page_end','artifact_digest','product_key','schema_digest','recipe_digest','native_schema_version','document_json','health','parent_task_id','parent_product_key','parent_digest','items','regions','recognition_coverage','runtime_report','cell_reports','inline_alignment_reports','inline_candidate_pages','derivation_mappings'])) OR NOT (parsing_item ? 'recipe') OR (parsing_item ? 'recipe' AND (jsonb_typeof(parsing_item->'recipe') IS DISTINCT FROM 'string' OR parsing_item->>'recipe' NOT IN ('pdf-native-v1'))) OR NOT (parsing_item ? 'source_scope') OR (parsing_item ? 'source_scope' AND (jsonb_typeof(parsing_item->'source_scope') IS DISTINCT FROM 'string')) OR (parsing_item ? 'source_scope' AND parsing_item->>'source_scope' !~ '^(whole_document|page_range)$') OR (parsing_item ? 'page_start' AND (jsonb_typeof(parsing_item->'page_start') IS DISTINCT FROM 'number' OR parsing_item->>'page_start' !~ '^[0-9]+$')) OR (parsing_item ? 'page_start' AND (parsing_item->>'page_start')::numeric < 1) OR (parsing_item ? 'page_end' AND (jsonb_typeof(parsing_item->'page_end') IS DISTINCT FROM 'number' OR parsing_item->>'page_end' !~ '^[0-9]+$')) OR (parsing_item ? 'page_end' AND (parsing_item->>'page_end')::numeric < 1) OR NOT (parsing_item ? 'artifact_digest') OR (parsing_item ? 'artifact_digest' AND (jsonb_typeof(parsing_item->'artifact_digest') IS DISTINCT FROM 'string')) OR (parsing_item ? 'artifact_digest' AND parsing_item->>'artifact_digest' !~ '^[0-9a-f]{64}$') OR NOT (parsing_item ? 'product_key') OR (parsing_item ? 'product_key' AND (jsonb_typeof(parsing_item->'product_key') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'schema_digest') OR (parsing_item ? 'schema_digest' AND (jsonb_typeof(parsing_item->'schema_digest') IS DISTINCT FROM 'string')) OR (parsing_item ? 'schema_digest' AND parsing_item->>'schema_digest' !~ '^[0-9a-f]{64}$') OR NOT (parsing_item ? 'recipe_digest') OR (parsing_item ? 'recipe_digest' AND (jsonb_typeof(parsing_item->'recipe_digest') IS DISTINCT FROM 'string')) OR (parsing_item ? 'recipe_digest' AND parsing_item->>'recipe_digest' !~ '^[0-9a-f]{64}$') OR NOT (parsing_item ? 'native_schema_version') OR (parsing_item ? 'native_schema_version' AND (jsonb_typeof(parsing_item->'native_schema_version') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'document_json') OR (parsing_item ? 'document_json' AND (jsonb_typeof(parsing_item->'document_json') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'health') OR (parsing_item ? 'health' AND (jsonb_typeof(parsing_item->'health') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(parsing_item->'health') key WHERE key<>ALL(ARRAY['conversion','display_coverage','inline_coverage','cell_coverage','issues','formula_outcomes','candidate_policy','cells_policy','inline_scope','cell_scope','inline_membership','cell_membership'])) OR NOT (parsing_item->'health' ? 'conversion') OR (parsing_item->'health' ? 'conversion' AND (jsonb_typeof(parsing_item->'health'->'conversion') IS DISTINCT FROM 'string' OR parsing_item->'health'->>'conversion' NOT IN ('failure','partial_success','success'))) OR NOT (parsing_item->'health' ? 'display_coverage') OR (parsing_item->'health' ? 'display_coverage' AND (jsonb_typeof(parsing_item->'health'->'display_coverage') IS DISTINCT FROM 'string' OR parsing_item->'health'->>'display_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (parsing_item->'health' ? 'inline_coverage') OR (parsing_item->'health' ? 'inline_coverage' AND (jsonb_typeof(parsing_item->'health'->'inline_coverage') IS DISTINCT FROM 'string' OR parsing_item->'health'->>'inline_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (parsing_item->'health' ? 'cell_coverage') OR (parsing_item->'health' ? 'cell_coverage' AND (jsonb_typeof(parsing_item->'health'->'cell_coverage') IS DISTINCT FROM 'string' OR parsing_item->'health'->>'cell_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR (parsing_item->'health' ? 'issues' AND (jsonb_typeof(parsing_item->'health'->'issues') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'health'->'issues') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (parsing_item->'health' ? 'formula_outcomes' AND (jsonb_typeof(parsing_item->'health'->'formula_outcomes') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'health'->'formula_outcomes') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['pointer','outcome','error'])) OR NOT (nested_record ? 'pointer') OR (nested_record ? 'pointer' AND (jsonb_typeof(nested_record->'pointer') IS DISTINCT FROM 'string')) OR (nested_record ? 'pointer' AND nested_record->>'pointer' !~ '^#(/[^/]+)+$') OR NOT (nested_record ? 'outcome') OR (nested_record ? 'outcome' AND (jsonb_typeof(nested_record->'outcome') IS DISTINCT FROM 'string' OR nested_record->>'outcome' NOT IN ('failed','not_requested','succeeded','unknown'))) OR (nested_record ? 'error' AND (jsonb_typeof(nested_record->'error') IS DISTINCT FROM 'string')))))) OR (parsing_item->'health' ? 'candidate_policy' AND (jsonb_typeof(parsing_item->'health'->'candidate_policy') IS DISTINCT FROM 'string' OR parsing_item->'health'->>'candidate_policy' NOT IN ('native-font-token-vector-ocr-word-v3','native-font-token-vector-v2','native-math-font-or-token-v1'))) OR (parsing_item->'health' ? 'cells_policy' AND (jsonb_typeof(parsing_item->'health'->'cells_policy') IS DISTINCT FROM 'string' OR parsing_item->'health'->>'cells_policy' NOT IN ('all-nonempty-selected-cells-v1'))) OR (parsing_item->'health' ? 'inline_scope' AND (jsonb_typeof(parsing_item->'health'->'inline_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'health'->'inline_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (parsing_item->'health' ? 'inline_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(parsing_item->'health'->'inline_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (parsing_item->'health' ? 'cell_scope' AND (jsonb_typeof(parsing_item->'health'->'cell_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'health'->'cell_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (parsing_item->'health' ? 'cell_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(parsing_item->'health'->'cell_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (parsing_item->'health' ? 'inline_membership' AND (jsonb_typeof(parsing_item->'health'->'inline_membership') IS DISTINCT FROM 'string' OR parsing_item->'health'->>'inline_membership' NOT IN ('descendants','direct'))) OR (parsing_item->'health' ? 'cell_membership' AND (jsonb_typeof(parsing_item->'health'->'cell_membership') IS DISTINCT FROM 'string' OR parsing_item->'health'->>'cell_membership' NOT IN ('descendants','direct')))))) OR (parsing_item ? 'parent_task_id' AND (jsonb_typeof(parsing_item->'parent_task_id') IS DISTINCT FROM 'number' OR parsing_item->>'parent_task_id' !~ '^[0-9]+$')) OR (parsing_item ? 'parent_task_id' AND (parsing_item->>'parent_task_id')::numeric < 1) OR (parsing_item ? 'parent_product_key' AND (jsonb_typeof(parsing_item->'parent_product_key') IS DISTINCT FROM 'string')) OR (parsing_item ? 'parent_digest' AND (jsonb_typeof(parsing_item->'parent_digest') IS DISTINCT FROM 'string')) OR (parsing_item ? 'parent_digest' AND parsing_item->>'parent_digest' !~ '^[0-9a-f]{64}$') OR NOT (parsing_item ? 'items') OR (parsing_item ? 'items' AND (jsonb_typeof(parsing_item->'items') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(parsing_item->'items') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_